$(document).ready(function () {
    const PromptInput = $("#chat-input");
    const SendBtn = $("#send-btn");
    const ChatContainer = $(".chat-container");
    const ThemeBtn = $("#theme-btn");
    const DeleteBtn = $("#delete-btn");

    const CreateChatElement = (html, className) => {
        return $("<div></div>").addClass(`chat ${className}`).html(html);
    };

    const LoadFromLocalStorage = () => {
        const theme = localStorage.getItem("Theme-Switcher") || "light_mode";
        $("body").toggleClass("light-mode", theme === "light_mode");
        ThemeBtn.text(theme);

        const chats = localStorage.getItem("All-Chats") || `
            <div class="Default-Text">
                <h1>Buddhi Babu</h1>
                <p>Future of AI !</p>
            </div>`;
        ChatContainer.html(chats);
        ChatContainer.scrollTop(ChatContainer.prop("scrollHeight"));
    };

    const FetchResponses = async (chatDiv) => {
        const pElement = $("<p></p>");
        try {
            SendBtn.prop("disabled", true);
            const response = await $.post('/chat-fetch', {
                prompt: PromptInput.val().trim(),
                _token: "{{ csrf_token() }}"
            });
            pElement.html(response.result.trim());
        } catch (error) {
            pElement.addClass("error").text(
                error.responseJSON?.message?.includes("LANGUAGE")
                    ? "Oops! I can only speak English. Please try again with different input."
                    : "Oops something went wrong while getting responses, please try again."
            );
        }
        chatDiv.find(".loading-dots-animation").remove();
        chatDiv.find(".chat-details").append(pElement);
        ChatContainer.scrollTop(ChatContainer.prop("scrollHeight"));
        localStorage.setItem("All-Chats", ChatContainer.html());
        SendBtn.prop("disabled", false);
    };

    const StartTypingAnimation = () => {
        const html = `
            <div class="chat-content-box">
                <div class="chat-details">
                    <img src="https://i.ibb.co/crKsfZc/blue-modern-robotic-logo.png" alt="chatbot-image">
                    <div class="loading-dots-animation">
                        <div class="loading-dot" style="--delay:0.2s;"></div>
                        <div class="loading-dot" style="--delay:0.3s;"></div>
                        <div class="loading-dot" style="--delay:0.4s;"></div>
                    </div>
                </div>
                <span class="material-symbols-rounded">content_copy</span>
            </div>`;
        const incomingChatDiv = CreateChatElement(html, "incoming");
        ChatContainer.append(incomingChatDiv);
        ChatContainer.scrollTop(ChatContainer.prop("scrollHeight"));
        FetchResponses(incomingChatDiv);
    };

    const AddOutgoingChat = () => {
        const userPrompt = PromptInput.val().trim();
        if (!userPrompt) return;
        const html = `
            <div class="chat-content-box">
                <div class="chat-details">
                    <img src="https://charmouthtennisclub.org/wp-content/uploads/2021/01/placeholder-400x400.jpg" alt="user-image">
                    <p></p>
                </div>
            </div>`;
        const outgoingChatDiv = CreateChatElement(html, "outgoing");
        ChatContainer.append(outgoingChatDiv);
        outgoingChatDiv.find("p").text(userPrompt);
        $(".Default-Text").remove();
        ChatContainer.scrollTop(ChatContainer.prop("scrollHeight"));
        setTimeout(StartTypingAnimation, 500);
    };

    ThemeBtn.on("click", () => {
        const isLightMode = $("body").hasClass("light-mode");
        $("body").toggleClass("light-mode", !isLightMode);
        const newTheme = isLightMode ? "dark_mode" : "light_mode";
        localStorage.setItem("Theme-Switcher", newTheme);
        ThemeBtn.text(newTheme);
    });

    DeleteBtn.on("click", () => {
        if (confirm("Are you sure you want to delete all chats?")) {
            localStorage.removeItem("All-Chats");
            LoadFromLocalStorage();
        }
    });

    PromptInput.on("input", () => {
        PromptInput.height("auto").height(PromptInput.prop("scrollHeight"));
    });

    PromptInput.on("keydown", (e) => {
        if (e.key === "Enter" && !e.shiftKey && $(window).width() > 800) {
            e.preventDefault();
            AddOutgoingChat();
        }
    });

    SendBtn.on("click", AddOutgoingChat);

    LoadFromLocalStorage(); // Initial load from local storage
});
